-- Project map-field audit (read-only)
--
-- Purpose:
--   Reports country, status, and project-type values that can keep projects
--   off the overview map or prevent the proposed constraints from validating.
--
-- This script is read-only. Run each section independently in the Supabase SQL
-- editor or via psql. The canonical geography VALUES block is generated by:
--
--   pnpm generate:geographies
--
-- Do not edit the generated block by hand.

-- ============================================================================
-- Section 1: coverage summary
-- ============================================================================
SELECT
  count(*) AS total_projects,
  count(*) FILTER (WHERE project_status = 'Active') AS active_projects_exact,
  count(*) FILTER (
    WHERE lower(btrim(coalesce(project_status, ''))) = 'active'
      AND project_status IS DISTINCT FROM 'Active'
  ) AS active_status_variants,
  count(*) FILTER (
    WHERE project_status = 'Active'
      AND project_country IS NULL
  ) AS active_with_null_country,
  count(*) FILTER (
    WHERE project_status = 'Active'
      AND btrim(coalesce(project_country, '')) = ''
  ) AS active_with_blank_country,
  count(DISTINCT project_country) FILTER (
    WHERE project_country IS NOT NULL
      AND btrim(project_country) <> ''
  ) AS distinct_country_values_raw,
  count(DISTINCT lower(btrim(project_country))) FILTER (
    WHERE project_country IS NOT NULL
      AND btrim(project_country) <> ''
  ) AS distinct_country_values_normalised
FROM public.projects;

