),
known_aliases(raw_value, proposed_value, requires_signoff) AS (
  VALUES
    ('Ascension Island', 'Ascension', false),
    ('BVI', 'British Virgin Islands', false),
    ('England', NULL, true),
    ('Scotland', NULL, true),
    ('England, Scotland', NULL, true),
    ('French Polynseia', 'French Polynesia', false),
    ('Saint Helena', 'St Helena', false),
    ('St Helena Island', 'St Helena', false),
    ('Sao Tome', 'São Tomé and Príncipe', false),
    ('St Kitts and Nevis', 'Saint Kitts and Nevis', false),
    ('St Kitts & Nevis', 'Saint Kitts and Nevis', false),
    (
      'St Vincent and the Grenadines',
      'Saint Vincent and the Grenadines',
      false
    ),
    ('United Kingdom, EU', NULL, true)
),
country_counts AS (
  SELECT
    project_country AS raw_value,
    count(*) AS project_count,
    count(*) FILTER (WHERE project_status = 'Active') AS active_project_count
  FROM public.projects
  GROUP BY project_country
)
SELECT
  counts.raw_value,
  counts.project_count,
  counts.active_project_count,
  counts.raw_value IS NULL AS is_null,
  counts.raw_value IS NOT NULL
    AND btrim(counts.raw_value) = '' AS is_blank,
  counts.raw_value IS DISTINCT FROM btrim(counts.raw_value) AS has_outer_space,
  canonical.name IS NOT NULL AS is_canonical,
  alias.raw_value IS NOT NULL AS is_known_alias,
  alias.proposed_value,
  coalesce(alias.requires_signoff, false) AS requires_signoff,
  counts.raw_value IS NOT NULL
    AND btrim(counts.raw_value) <> ''
    AND canonical.name IS NULL
    AND alias.raw_value IS NULL AS is_unknown
FROM country_counts counts
LEFT JOIN canonical_geographies canonical
  ON canonical.name = btrim(counts.raw_value)
LEFT JOIN known_aliases alias
  ON alias.raw_value = btrim(counts.raw_value)
ORDER BY
  requires_signoff DESC,
  is_unknown DESC,
  has_outer_space DESC,
  counts.active_project_count DESC,
  counts.project_count DESC,
  counts.raw_value NULLS FIRST;

-- ============================================================================
-- Section 3: country values that differ only by case or outer whitespace
-- ============================================================================
SELECT
  lower(btrim(project_country)) AS normalised_value,
  array_agg(DISTINCT project_country ORDER BY project_country) AS raw_variants,
  count(*) AS project_count,
  count(*) FILTER (WHERE project_status = 'Active') AS active_project_count
FROM public.projects
WHERE project_country IS NOT NULL
  AND btrim(project_country) <> ''
GROUP BY lower(btrim(project_country))
HAVING count(DISTINCT project_country) > 1
ORDER BY project_count DESC, normalised_value;

-- ============================================================================
-- Section 4: status values
-- The validated CHECK permits Pipeline, Active, Complete, or NULL.
-- ============================================================================
SELECT
  project_status AS raw_value,
  count(*) AS project_count,
  project_status IS NULL AS is_null,
  project_status IS DISTINCT FROM btrim(project_status) AS has_outer_space,
  btrim(project_status) IN ('Pipeline', 'Active', 'Complete') AS is_canonical,
  false AS requires_signoff,
  project_status IS NOT NULL
    AND btrim(project_status) NOT IN (
      'Pipeline',
      'Active',
      'Complete'
    ) AS is_unknown
FROM public.projects
GROUP BY project_status
ORDER BY requires_signoff DESC, is_unknown DESC, project_count DESC, raw_value;

-- ============================================================================
-- Section 5: project-type values
-- ============================================================================
SELECT
  project_type AS raw_value,
  count(*) AS project_count,
  project_type IS NULL AS is_null,
  project_type IS DISTINCT FROM btrim(project_type) AS has_outer_space,
  btrim(project_type) IN (
    'Project',
    'Unit led project',
    'Unit'
  ) AS is_canonical,
  btrim(project_type) NOT IN (
    'Project',
    'Unit led project',
    'Unit'
  ) AS is_unknown
FROM public.projects
GROUP BY project_type
ORDER BY is_unknown DESC, project_count DESC, raw_value;
